import React, { useState } from 'react';
import { Menu, X, Search, User } from 'lucide-react';
import { MENU_ITEMS } from '../constants';

const Header: React.FC = () => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  return (
    <header className="sticky top-0 z-50 shadow-md">
      {/* Top Brand Bar */}
      <div className="bg-white px-4 py-3 flex justify-between items-center border-b border-gray-100">
        <div className="flex items-center gap-4">
          <button 
            className="md:hidden text-gray-600"
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
          >
            {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
          <a href="#" className="text-2xl font-black text-arata-blue tracking-tighter uppercase">
            ARATA
          </a>
        </div>

        <div className="flex items-center gap-3">
          <div className="hidden md:flex relative">
            <input 
              type="text" 
              placeholder="작품을 검색하세요" 
              className="bg-gray-100 rounded-full py-1.5 px-4 text-sm w-64 focus:outline-none focus:ring-2 focus:ring-arata-blue"
            />
            <Search className="absolute right-3 top-1.5 text-gray-400" size={18} />
          </div>
          <button className="p-2 text-gray-600 hover:text-arata-blue transition-colors">
            <User size={24} />
          </button>
        </div>
      </div>

      {/* Main Navigation Bar (Blue) */}
      <nav className="bg-arata-blue text-white hidden md:block">
        <div className="max-w-7xl mx-auto flex">
          {/* Home Icon Block */}
          <a href="#" className="bg-blue-700 px-6 py-4 hover:bg-blue-800 transition-colors">
            <Menu size={20} />
          </a>

          {/* Nav Items */}
          <div className="flex flex-1">
            {MENU_ITEMS.map((item) => (
              <a 
                key={item.id} 
                href={item.path}
                className="flex items-center px-8 py-4 font-medium hover:bg-blue-500 transition-colors text-base"
              >
                {item.label}
              </a>
            ))}
          </div>
        </div>
      </nav>

      {/* Mobile Menu */}
      {isMobileMenuOpen && (
        <div className="md:hidden bg-arata-blue text-white animate-fade-in">
          {MENU_ITEMS.map((item) => (
            <a 
              key={item.id} 
              href={item.path}
              className="block px-6 py-4 border-b border-blue-500 hover:bg-blue-500 flex items-center gap-3"
