import React, { useRef } from 'react';
import { Webtoon } from '../types';
import { LATEST_WEBTOONS } from '../constants';
import WebtoonCard from './WebtoonCard';
import { ChevronRight, ChevronLeft, ChevronRight as ArrowIcon } from 'lucide-react';
import { Link } from 'react-router-dom';

interface WebtoonSectionProps {
  title: string;
  webtoons?: Webtoon[];
  type?: 'grid' | 'row';
}

const WebtoonGrid: React.FC<WebtoonSectionProps> = ({ title, webtoons = LATEST_WEBTOONS, type = 'grid' }) => {
  const scrollRef = useRef<HTMLDivElement>(null);

  const scroll = (direction: 'left' | 'right') => {
    if (scrollRef.current) {
      const { current } = scrollRef;
      const scrollAmount = direction === 'left' ? -current.clientWidth * 0.7 : current.clientWidth * 0.7;
      current.scrollBy({ left: scrollAmount, behavior: 'smooth' });
    }
  };

  return (
    <section className="mb-10 px-4 md:px-0 relative group/section">
      {/* Section Header */}
      <div className="flex justify-between items-end mb-4 px-2">
        <h2 className="text-xl md:text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
           {title}
           <ArrowIcon size={20} className="text-arata-green opacity-0 group-hover/section:opacity-100 -translate-x-2 group-hover/section:translate-x-0 transition-all duration-300" />
        </h2>
        <Link to="/unlimited" className="text-xs md:text-sm font-bold text-gray-500 hover:text-arata-green transition-colors">
            전체보기
        </Link>
      </div>

      {type === 'row' ? (
        /* Horizontal Rail Layout */
        <div className="relative group">
            {/* Left Button */}
            <button 
                onClick={() => scroll('left')}
                className="absolute left-0 top-0 bottom-0 w-12 bg-gradient-to-r from-white dark:from-arata-black to-transparent z-20 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-300 disabled:opacity-0"
            >
                <ChevronLeft size={32} className="text-gray-900 dark:text-white drop-shadow-lg hover:scale-125 transition-transform" />
            </button>

            {/* Scroll Container */}
            <div 
                ref={scrollRef}
                className="flex gap-4 md:gap-5 overflow-x-auto no-scrollbar py-4 px-2 snap-x"
            >
                {webtoons.map((webtoon) => (
                <div key={webtoon.id} className="flex-shrink-0 w-[140px] md:w-[200px] snap-start">
                    <WebtoonCard webtoon={webtoon} />
                </div>
                ))}
            </div>

            {/* Right Button */}
            <button 
                onClick={() => scroll('right')}
                className="absolute right-0 top-0 bottom-0 w-12 bg-gradient-to-l from-white dark:from-arata-black to-transparent z-20 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-300"
            >
                <ChevronRight size={32} className="text-gray-900 dark:text-white drop-shadow-lg hover:scale-125 transition-transform" />
            </button>
        </div>
      ) : (
        /* Standard Grid Layout */
        <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-x-4 gap-y-8 px-2">
          {webtoons.map((webtoon) => (
            <WebtoonCard key={webtoon.id} webtoon={webtoon} />
          ))}
        </div>
      )}
    </section>
  );
};

export default WebtoonGrid;

